package net.minecraft.world.entity.monster;import java.util.*;import net.minecraft.network.syncher.SynchedEntityData;import net.minecraft.nbt.CompoundTag;import net.minecraft.world.entity.ai.attributes.*;import net.minecraft.resources.ResourceLocation;
public class Zombie extends net.minecraft.world.entity.Entity{public static class Level{public boolean isClientSide;}public static class Point{public double x,y,z;public Point(double x,double y,double z){this.x=x;this.y=y;this.z=z;}public Point scale(double s){return new Point(x*s,y*s,z*s);}public Point add(double a,double b,double c){return new Point(x+a,y+b,z+c);}public Point add(Point p){return add(p.x,p.y,p.z);}}public static class Attr{public Map<ResourceLocation,AttributeModifier> mods=new HashMap<>();public void removeModifier(ResourceLocation id){mods.remove(id);}public boolean hasModifier(ResourceLocation id){return mods.containsKey(id);}public void addTransientModifier(AttributeModifier m){mods.put(m.id(),m);}public void addPermanentModifier(AttributeModifier m){mods.put(m.id(),m);}}
public final Level world=new Level();public final SynchedEntityData data=new SynchedEntityData();public final CompoundTag tag=new CompoundTag();public final Attr speed=new Attr(),healthAttribute=new Attr();public float health=20,yBodyRot;public int tickCount,refresh,pushes;public boolean burning,hurtMarked,hasImpulse;public Point hit=new Point(0,1.75,0);public void push(double x,double y,double z){pushes++;}public Object level(){return world;}public SynchedEntityData getEntityData(){return data;}public CompoundTag getPersistentData(){return tag;}public float getMaxHealth(){return 20f*(1+(float)healthAttribute.mods.values().stream().mapToDouble(AttributeModifier::amount).sum());}public float getHealth(){return health;}public void setHealth(float h){health=Math.min(h,getMaxHealth());}public float getBbHeight(){return 2;}public float getYRot(){return 0;}public Point position(){return new Point(0,0,0);}public void refreshDimensions(){refresh++;}public Attr getAttribute(Object holder){return holder==Attributes.MAX_HEALTH?healthAttribute:speed;}public boolean isOnFire(){return burning;}public class Bounds{public Optional<Point> clip(Point start,Point end){return Optional.of(hit);}}public Bounds getBoundingBox(){return new Bounds();}}
